    private void btnCadastrarLojaActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCadastrarLojaActionPerformed
        String nome = txtNomeLoja.getText();
        String documento = txtDocumento.getText();
        String email = txtEmail.getText();
        String ramoVendas = txtRamoVendas.getText();
        
        String tipo = "Loja";
        if (RBvendedor.isSelected()){
            tipo = "Vendedor";
        }
        
        if (nome.isEmpty() || documento.isEmpty() || email.isEmpty()) {
    javax.swing.JOptionPane.showMessageDialog(this, "Por favor, preencha todos os campos obrigatórios!");
    return;
     }
        
        Classes.Participante p = new Classes.Participante();
        p.setNome(nome);
        p.setDocumento(documento);
        p.setEmail(email);
        p.setRamoVendas(ramoVendas);
        p.setTipo(tipo);
        
        DAOs.ParticipanteDAO dao = new DAOs.ParticipanteDAO();
        int idGerado = dao.cadastrar(p);
        
       if (idGerado != -1) {
    
         p.setId(idGerado);
    
    javax.swing.JOptionPane.showMessageDialog(this, "Cadastro realizado com sucesso!");

   
    Perfil telaPerfil = new Perfil(p); 
    telaPerfil.setVisible(true); 
    this.dispose(); 
} else {
    javax.swing.JOptionPane.showMessageDialog(this, "Erro ao conectar com o banco de dados ou salvar o cadastro.");
}
        
        
    }//GEN-LAST:event_btnCadastrarLojaActionPerformed

    private void btnLoginActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLoginActionPerformed
        String documentoLogin = javax.swing.JOptionPane.showInputDialog(this, "Informe o número do seu documento (CPF/CNPJ) para entrar:");

if (documentoLogin != null && !documentoLogin.trim().isEmpty()) {
 
    DAOs.ParticipanteDAO dao = new DAOs.ParticipanteDAO();
    Classes.Participante p = dao.buscarPorDocumento(documentoLogin.trim());
    

    if (p != null) {
        javax.swing.JOptionPane.showMessageDialog(this, "Login realizado com sucesso! Bem-vindo de volta, " + p.getNome());
              
        Perfil telaPerfil = new Perfil(p);
        telaPerfil.setVisible(true);
       
        this.dispose();
    } else {
        javax.swing.JOptionPane.showMessageDialog(this, "Nenhuma conta encontrada com este documento.", "Erro de Login", javax.swing.JOptionPane.ERROR_MESSAGE);
    }
}
    }//GEN-LAST:event_btnLoginActionPerformed

